package com.cyancoder.media.controller;
import com.cyancoder.media.model.MediaAssetContracts.*;import com.cyancoder.media.model.MediaUploadEntity;import com.cyancoder.media.service.MediaOperatorService;import org.springframework.core.io.Resource;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/endpoint/media/assets") public class EndpointMediaAssetController{private final MediaOperatorService service;public EndpointMediaAssetController(MediaOperatorService s){service=s;}@GetMapping @PreAuthorize("@platformAuthorizationService.canUseCapability('media:read')")public AssetPage list(@RequestHeader("X-Tenant-Key")String t,@RequestHeader(value="X-Site-Key",required=false)String s,Authentication a,@RequestParam(required=false)String q,@RequestParam(required=false)String type,@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="24")int size){return service.list(t,s,a.getName(),q,type,status,page,size);}@GetMapping("/{key}")@PreAuthorize("@platformAuthorizationService.canUseCapability('media:read')")public AssetItem get(@PathVariable String key,@RequestHeader("X-Tenant-Key")String t,@RequestHeader(value="X-Site-Key",required=false)String s,Authentication a){return service.get(t,s,a.getName(),key);}@PatchMapping("/{key}")@PreAuthorize("@platformAuthorizationService.canUseCapability('media:write')")public AssetItem update(@PathVariable String key,@RequestHeader("X-Tenant-Key")String t,@RequestHeader(value="X-Site-Key",required=false)String s,Authentication a,@RequestBody UpdateAssetRequest r){return service.update(t,s,a.getName(),key,r);}@GetMapping("/{key}/usage")@PreAuthorize("@platformAuthorizationService.canUseCapability('media:read')")public UsageResponse usage(@PathVariable String key,@RequestHeader("X-Tenant-Key")String t,@RequestHeader(value="X-Site-Key",required=false)String s,Authentication a){return service.usage(t,s,a.getName(),key);}@DeleteMapping("/{key}")@ResponseStatus(HttpStatus.NO_CONTENT)@PreAuthorize("@platformAuthorizationService.canUseCapability('media:write')")public void delete(@PathVariable String key,@RequestHeader("X-Tenant-Key")String t,@RequestHeader(value="X-Site-Key",required=false)String s,Authentication a){service.delete(t,s,a.getName(),key);}@GetMapping("/{key}/content")@PreAuthorize("@platformAuthorizationService.canUseCapability('media:read')")public ResponseEntity<Resource> content(@PathVariable String key,@RequestHeader("X-Tenant-Key")String t,@RequestHeader(value="X-Site-Key",required=false)String s,Authentication a){AssetItem item=service.get(t,s,a.getName(),key);return ResponseEntity.ok().contentType(MediaType.parseMediaType(item.mimeType())).header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename*=UTF-8''"+org.springframework.web.util.UriUtils.encodePathSegment(item.originalFileName(),java.nio.charset.StandardCharsets.UTF_8)).body(service.privateContent(t,s,a.getName(),key));}}
